plist.dict:
CFBundlePackageType
APPL
CFBundleName
{{.Info.ProductName}}
CFBundleExecutable
{{.OutputFilename}}
CFBundleIdentifier
io.github.snowdreamtech.unigodesktop
CFBundleVersion
{{.Info.ProductVersion}}
CFBundleGetInfoString
{{.Info.Comments}}
CFBundleShortVersionString
{{.Info.ProductVersion}}
CFBundleIconFile
iconfile
LSMinimumSystemVersion
10.13.0
NSHighResolutionCapable
true
NSHumanReadableCopyright
{{.Info.Copyright}}
CFBundleDevelopmentRegion
zh_CN
CFBundleAllowMixedLocalizations

CFBundleLocalizations

    zh_CN
    zh-Hans
    zh-Hant
    zh_TW
    en
    ja
    ko
    de
    fr
    es
    ru
    pt
    it

{{if .Info.FileAssociations}}
CFBundleDocumentTypes

  {{range .Info.FileAssociations}}

    CFBundleTypeExtensions

      {{.Ext}}

    CFBundleTypeName
    {{.Name}}
    CFBundleTypeRole
    {{.Role}}
    CFBundleTypeIconFile
    {{.IconName}}

  {{end}}

{{end}}
{{if .Info.Protocols}}
CFBundleURLTypes

  {{range .Info.Protocols}}

        CFBundleURLName
        com.wails.{{.Scheme}}
        CFBundleURLSchemes

            {{.Scheme}}

        CFBundleTypeRole
        {{.Role}}

  {{end}}

{{end}}
NSAppTransportSecurity

    NSAllowsLocalNetworking
